package com.seatrush.common.id;

import java.util.UUID;

/**
 * Source of identifiers for new aggregates.
 *
 * <p>Ids are always generated by the application, never by the database: an order id is known
 * before the row exists, so it can travel in a Kafka message, an idempotency record and a log line
 * written in the same transaction.
 */
public interface IdGenerator {

  /** Returns a fresh, time-ordered identifier. */
  UUID newId();
}
